// Block (multi-RHS) restarted GMRES(m): Krylov.bgmres(in A, in B, ref X) where B/X are s ROWS x n COLS
// (row = RHS). A is a GENERAL non-symmetric square matrix. A true block method (one shared block-Krylov
// subspace built by block Arnoldi via ApplyBlock, deflating rank-revealing LQRP per step, block-Hessenberg
// least-squares), NOT s independent scalar gmres solves. Unlike bbiCGStab, bgmres owns its ENTIRE workspace
// internally via Allocator.Temp (no ref scratch params). A rank-deficient RHS block deflates GRACEFULLY (the
// active search width w[0] shrinks below s) rather than breaking down. Every test runs inside a
// [BurstCompile] IJob (by-value struct copy), so the job-safety criterion -- the caller sees the final X
// written through the ref doubleMxN -- is exercised by construction.
public class doubleBlockGmresTests
{
    [BurstCompile(CompileSynchronously = true)]
    public struct BlockGmresTestJob : IJob
    {
        public enum TestType
        {
            MatchesScalarGmresPerColumn,
            KnownSolutionRecovered,
            RestartCorrectness,
            IdentityFoldBitIdentical,
            DeflatesRankDeficientRHSBlock,
            PreconditionedMatchesScalar,
        }

        public TestType Type;

        public void Execute()
        {
            switch (Type)
            {
                case TestType.MatchesScalarGmresPerColumn:   MatchesScalarGmresPerColumn();   break;
                case TestType.KnownSolutionRecovered:        KnownSolutionRecovered();        break;
                case TestType.RestartCorrectness:            RestartCorrectness();            break;
                case TestType.IdentityFoldBitIdentical:      IdentityFoldBitIdentical();      break;
                case TestType.DeflatesRankDeficientRHSBlock: DeflatesRankDeficientRHSBlock(); break;
                case TestType.PreconditionedMatchesScalar:   PreconditionedMatchesScalar();   break;
            }
        }

        // Block and per-column scalar GMRES both converge to residual ~ tol on the same unique solution of a
        // well-conditioned system, so the two agree well within this bound. Mirrors BlockBiCGStabTests' Tol().
        static double Tol() => 1e-5;

        // Diagonally dominant (so nonsingular) but NOT symmetrized -> genuinely non-symmetric. Do NOT form
        // M^T M (that would make it symmetric, defeating the point of a GMRES test).
        static doubleMxN BuildDenseNonsymmetric(int dim, uint seed)
        {
            var A = GenerateOP.doubleRandomMat(dim, dim, (double)(-1f), (double)1f, seed, Allocator.Temp);
            for (int d = 0; d < dim; d++) A[d, d] += dim;   // diagonally dominant -> nonsingular, nonsymmetric
            return A;
        }

        static doubleN Row(in doubleMxN B, int j, int n)
        {
            var v = new doubleN(n, Allocator.Temp);
            for (int c = 0; c < n; c++) v[c] = B[j, c];
            return v;
        }

        // Each column of the block solution matches an independent scalar gmres solve of that column, and
        // every column reached tolerance.
        void MatchesScalarGmresPerColumn()
        {
            int n = 20, s = 4;
            var A = BuildDenseNonsymmetric(n, 71001u);
            var B = GenerateOP.doubleRandomMat(s, n, (double)(-1f), (double)1f, 71002u, Allocator.Temp);

            int restart = n;             // full block subspace -> converges within one cycle
            int maxIter = 4 * n;
            double tol = Consts.doubleSqrtEps;

            var X = new doubleMxN(s, n, Allocator.Temp);   // zero initial guess
            var info = Krylov.bgmres(in A, in B, ref X, restart, maxIter, tol);

            Assert.IsTrue(info.Solved);
            Assert.AreEqual(s, info.converged);
            Assert.AreEqual(s, info.rhs);

            for (int j = 0; j < s; j++)
            {
                var bj = Row(in B, j, n);
                var xj = new doubleN(n, Allocator.Temp);
                Assert.IsTrue(Krylov.gmres(in A, in bj, ref xj, restart, maxIter, tol).Solved);

                // Block column j matches the scalar solve (both converged to the same unique solution).
                for (int c = 0; c < n; c++)
                    Assert.IsTrue(math.abs((double)X[j, c] - (double)xj[c]) <= Tol() * (1.0 + math.abs((double)xj[c])));
            }
        }

        // Independent of any other solver: pick a KNOWN block solution Xk, form B = A Xk via the GENERAL
        // block apply (doubleDenseOperatorGeneral -- doubleDenseOperator.ApplyBlock computes A^T for a
        // non-symmetric A and would build the WRONG B here), solve, and recover Xk.
        void KnownSolutionRecovered()
        {
            int n = 20, s = 5;
            var A = BuildDenseNonsymmetric(n, 72001u);
            var Xk = GenerateOP.doubleRandomMat(s, n, (double)(-1f), (double)1f, 72002u, Allocator.Temp);   // known solution

            var B = new doubleMxN(s, n, Allocator.Temp);
            new doubleDenseOperatorGeneral(in A).ApplyBlock(in Xk, ref B, s);          // B[j,:] = A Xk[j,:]

            var X = new doubleMxN(s, n, Allocator.Temp);
            var info = Krylov.bgmres(in A, in B, ref X, n, 4 * n, Consts.doubleSqrtEps);
            Assert.IsTrue(info.Solved);

            for (int j = 0; j < s; j++)
                for (int c = 0; c < n; c++)
                    Assert.IsTrue(math.abs((double)X[j, c] - (double)Xk[j, c]) <= Tol() * (1.0 + math.abs((double)Xk[j, c])));
        }

        // A restart well below the number of block steps this system needs forces multiple restart cycles:
        // one cycle of only `restart` block-Arnoldi steps cannot reach tolerance, so the solver must restart
        // at least once. Assert full convergence AND that MORE than `restart` total block steps were taken
        // (proving a real restart happened, not a trivial cycle-1 convergence). This n/s system needs ~4
        // total block steps at float's sqrtEps (~3.5e-4) and ~8 at double's (~1.5e-8); restart = 2 sits
        // comfortably below BOTH (float: 4 > 2 across two cycles; double: 8 > 2), so the restart is genuine
        // for every generated type, not a per-type knife's edge.
        void RestartCorrectness()
        {
            int n = 40, s = 3;
            var A = BuildDenseNonsymmetric(n, 73001u);
            var B = GenerateOP.doubleRandomMat(s, n, (double)(-1f), (double)1f, 73002u, Allocator.Temp);

            int restart = 2;             // << the block steps this system needs -> forces >=2 cycles for both types
            int maxIter = 10 * n;        // generous -> several restart cycles can finish converging
            double tol = Consts.doubleSqrtEps;

            var X = new doubleMxN(s, n, Allocator.Temp);
            var info = Krylov.bgmres(in A, in B, ref X, restart, maxIter, tol);

            Assert.IsTrue(info.Solved);
            Assert.IsTrue(info.iterations > restart);   // at least one restart actually happened
        }

        // The explicit-identity-preconditioner generic core must fold to EXACTLY the unpreconditioned
        // overload -- bit-identical X, iterations, status. bgmres owns its whole workspace internally
        // (Allocator.Temp), so there are no ref scratch params to pass, unlike bbiCGStab.
        void IdentityFoldBitIdentical()
        {
            int n = 16, s = 3;
            var A = BuildDenseNonsymmetric(n, 74001u);
            var B = GenerateOP.doubleRandomMat(s, n, (double)(-1f), (double)1f, 74002u, Allocator.Temp);
            int restart = 8;             // < n -> exercises restarts, still bit-identical across both paths
            int maxIter = 4 * n;
            double tol = Consts.doubleSqrtEps;

            var opA = new doubleDenseOperatorGeneral(in A);   // readonly struct -- construct once, reuse the value

            var X1 = new doubleMxN(s, n, Allocator.Temp);
            var info1 = Krylov.bgmres<doubleDenseOperatorGeneral, doubleIdentityPreconditioner>(
                in opA, default(doubleIdentityPreconditioner), in B, ref X1, restart, maxIter, tol);

            var X2 = new doubleMxN(s, n, Allocator.Temp);
            var info2 = Krylov.bgmres<doubleDenseOperatorGeneral>(in opA, in B, ref X2, restart, maxIter, tol);

            Assert.AreEqual(info1.iterations, info2.iterations);
            Assert.IsTrue(info1.status == info2.status);
            // Bit-identical X (no tolerance) -- matches the codebase's determinism-check pattern (== via
            // IsTrue rather than the boxing Assert.AreEqual(float,float), which is not Burst-safe).
            for (int i = 0; i < s; i++)
                for (int c = 0; c < n; c++)
                    Assert.IsTrue(X1[i, c] == X2[i, c]);
        }

        // A rank-deficient RHS block (two identical ROWS) makes R0 (= initial residual B, since X0 = 0)
        // rank-deficient. Unlike bbiCGStab, this is NOT a breakdown: bgmres's block Arnoldi uses a
        // rank-revealing LQRP that GRACEFULLY DEFLATES the dependent direction (the active width w[0] drops
        // below s), so the solve still fully converges. Contract: Solved is true, minActive < rhs (deflation
        // triggered), the two duplicate-RHS solution rows agree, and every entry of X is finite.
        void DeflatesRankDeficientRHSBlock()
        {
            int n = 20, s = 4;
            var A = BuildDenseNonsymmetric(n, 75001u);
            var B = GenerateOP.doubleRandomMat(s, n, (double)(-1f), (double)1f, 75002u, Allocator.Temp);
            // Force row 2 identical to row 0 -> block RHS rank <= s-1 -> LQRP reveals w[0] < s on cycle 1.
            for (int c = 0; c < n; c++) B[2, c] = B[0, c];

            var X = new doubleMxN(s, n, Allocator.Temp);
            var info = Krylov.bgmres(in A, in B, ref X, n, 4 * n, Consts.doubleSqrtEps);

            // Converges (deflation is graceful, not a breakdown).
            Assert.IsTrue(info.Solved);
            // Deflation actually triggered: the shared search width shrank below the RHS count.
            Assert.IsTrue(info.minActive < info.rhs);
            // Finite, no NaN/Inf.
            for (int j = 0; j < s; j++)
                for (int c = 0; c < n; c++)
                    Assert.IsFalse(double.IsNaN((double)X[j, c]) || double.IsInfinity((double)X[j, c]));
            // Identical RHS rows -> identical recovered solution rows.
            for (int c = 0; c < n; c++)
                Assert.IsTrue(math.abs((double)X[0, c] - (double)X[2, c]) <= Tol() * (1.0 + math.abs((double)X[0, c])));
        }

        // BSR non-symmetric diagonally-dominant A + ILU(0) preconditioner (build ONE M, reuse it for the
        // block and every scalar call). The block solve matches per-column scalar ILU(0)-preconditioned gmres.
        void PreconditionedMatchesScalar()
        {
            var A = doubleGallery.doubleRandomSparse(16, 16, 2, (double)0.4, 76001u, Allocator.Temp);   // 32 dof, nonsymmetric diag-dominant
            int n = A.M_Rows;
            int s = 3;
            var M = new doubleILU0(in A, Allocator.Temp);
            var B = GenerateOP.doubleRandomMat(s, n, (double)(-1f), (double)1f, 76002u, Allocator.Temp);

            int restart = n;
            int maxIter = 4 * n;
            double tol = Consts.doubleSqrtEps;

            var X = new doubleMxN(s, n, Allocator.Temp);
            var info = Krylov.bgmres(in A, in M, in B, ref X, restart, maxIter, tol);
            Assert.IsTrue(info.Solved);
            Assert.AreEqual(s, info.converged);

            for (int j = 0; j < s; j++)
            {
                var bj = Row(in B, j, n);
                var xj = new doubleN(n, Allocator.Temp);
                Assert.IsTrue(Krylov.gmres(in A, in M, in bj, ref xj, restart, maxIter, tol).Solved);
                for (int c = 0; c < n; c++)
                    Assert.IsTrue(math.abs((double)X[j, c] - (double)xj[c]) <= Tol() * (1.0 + math.abs((double)xj[c])));
            }
        }
    }

